<script setup lang="ts">
// SPDX-License-Identifier: AGPL-3.0-only
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {tagNameKey,existingTagName} from '../domain/tag-names'
import {useWorkspace} from '../state/workspace'
import {useLocale} from '../state/locale'
const props=defineProps<{modelValue:string;options:string[];disabled?:boolean;id:string;collapseInput?:boolean;newTags?:string[]}>(),emit=defineEmits<{'update:modelValue':[string]}>(),{t}=useLocale(),query=ref(''),opened=ref(false)
const store=useWorkspace(),known=ref<string[]>([]),unavailable=ref(false);let alive=true,generation=0
watch(()=>JSON.stringify([store.connection.value?.server,store.connection.value?.account]),async()=>{const version=++generation;known.value=[];query.value='';opened.value=false;unavailable.value=false;if(!store.connection.value)return;try{const value=await store.request('tag-options');if(alive&&version===generation){known.value=value.tags??[];unavailable.value=value.available===false}}catch{if(alive&&version===generation)unavailable.value=true}},{immediate:true});onBeforeUnmount(()=>{alive=false;generation++})
const selected=computed(()=>[...new Set(props.modelValue.split(',').map(v=>v.trim()).filter(Boolean))])
const catalog=computed(()=>[...known.value,...props.options.filter(tag=>!known.value.some(existing=>tagNameKey(existing)===tagNameKey(tag)))])
const choices=computed(()=>[...new Set(catalog.value)].filter(v=>!selected.value.some(tag=>tagNameKey(tag)===tagNameKey(v))&&v.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
const canCreate=computed(()=>!!query.value.trim()&&!query.value.includes(',')&&!selected.value.some(tag=>tagNameKey(tag)===tagNameKey(query.value))&&!catalog.value.some(tag=>tagNameKey(tag)===tagNameKey(query.value)))
function add(value:string){if(props.disabled)return;value=existingTagName(value,catalog.value);if(selected.value.some(tag=>tagNameKey(tag)===tagNameKey(value)))return;if(!value||value.includes(',')||value.length>80||/[\x00-\x1f\x7f]/.test(value))return;emit('update:modelValue',[...new Set([...selected.value,value.normalize('NFC')])].join(', '));query.value=''}
function remove(value:string){if(!props.disabled)emit('update:modelValue',selected.value.filter(v=>v!==value).join(', '))}
</script>
<template><div class="tag-picker"><div v-if="selected.length" class="selected-tags"><span v-for="tag in selected" :key="tag" class="tag">{{ tag }}<small v-if="newTags?.includes(tag)"> · {{ t('New tag') }}</small><button type="button" :disabled="disabled" :aria-label="t('Remove tag {tag}',{tag})" @click="remove(tag)">×</button></span></div><component :is="collapseInput?'details':'div'" class="manual-tag-input"><summary v-if="collapseInput">{{ t('Manually add existing tags') }}</summary><input :id="id" v-model="query" :disabled="disabled" maxlength="80" :placeholder="t('Find or create a tag')" autocomplete="off" @focus="opened=true" @keydown.enter.prevent="canCreate?add(query):choices.length===1?add(choices[0]!):undefined" /><div v-if="opened" class="tag-options" role="group" :aria-label="t('Available tags')"><button v-for="tag in choices" :key="tag" type="button" class="button tag-choice" :aria-label="t('Add tag {tag}',{tag})" :disabled="disabled" @click="add(tag)">{{ tag }}</button><button v-if="canCreate" type="button" class="button" :disabled="disabled" @click="add(query)">{{ t('Create tag {tag}',{tag:query.trim()}) }}</button></div><p v-if="unavailable" class="fine-print">{{ t('Some existing tags could not be loaded.') }}</p></component></div></template>
<style scoped>.manual-tag-input summary{cursor:pointer;color:var(--muted);font-size:12px;padding:8px 0}.manual-tag-input[open]>input{margin-top:6px}.selected-tags,.tag-options{display:flex;flex-wrap:wrap;gap:6px}.selected-tags{margin-bottom:10px}.tag-picker input{width:100%}.tag-options{max-height:160px;overflow:auto;margin-top:8px}.tag button{background:none;border:0;color:inherit;cursor:pointer;margin-left:6px;font-size:16px}</style>
